import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic input', () => {
  it('validates weather against the current location schema (spec: specs/hal-engine-tool-input-validation/spec.md#8)', async () => {
    const registry = new ToolRegistry();
    const textSchema = {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
    const numericSchema = {type: 'object', properties: {location: {type: 'number'}}, required: ['location']};
    let inputSchema = textSchema;
    const inputs: Record<string, unknown>[] = [];
    registry.register(
      () => ({name: 'weather', description: 'Weather by location', inputSchema}),
      async input => {
        inputs.push(input);
        return JSON.stringify(input);
      }
    );

    const textRejection = await registry.execute('weather', {location: 42});
    inputSchema = numericSchema;
    const numericRejection = await registry.execute('weather', {location: 'Berlin'});
    const accepted = await registry.execute('weather', {location: 42});
    inputSchema = textSchema;
    const repeatedRejection = await registry.execute('weather', {location: 42});

    expect({textRejection, numericRejection, accepted, repeatedRejection, inputs}).toEqual({
      textRejection: {result: expect.stringMatching(/location.*string/)},
      numericRejection: {result: expect.stringMatching(/location.*number/)},
      accepted: {result: '{\"location\":42}'},
      repeatedRejection: {result: expect.stringMatching(/location.*string/)},
      inputs: [{location: 42}],
    });
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/tools/registry.dynamic.test.ts"

